mapper.select:
SELECT * FROM payment_attempt
WHERE status = 'PROCESSING' AND query_count < #{maxQueryCount} AND next_query_at <= #{now}
  AND (query_lock_until IS NULL OR query_lock_until < #{now})
ORDER BY next_query_at, id LIMIT #{limit}

mapper.update:
UPDATE payment_attempt
SET query_lock_owner = #{owner}, query_claim_token = #{claimToken}, query_lock_until = #{lockUntil}
WHERE attempt_id = #{attemptId} AND status = 'PROCESSING' AND query_count < #{maxQueryCount}
  AND next_query_at <= #{now} AND (query_lock_until IS NULL OR query_lock_until < #{now})

UPDATE payment_attempt
SET query_count = query_count + 1, last_query_at = #{now}, next_query_at = #{nextQueryAt},
  query_lock_owner = NULL, query_lock_until = NULL, query_claim_token = NULL
WHERE attempt_id = #{attemptId} AND status = 'PROCESSING' AND query_claim_token = #{claimToken}
  AND query_lock_until >= #{now}

UPDATE payment_attempt
SET next_query_at = #{nextQueryAt}, query_lock_owner = NULL, query_lock_until = NULL, query_claim_token = NULL
WHERE attempt_id = #{attemptId} AND status = 'PROCESSING' AND query_claim_token = #{claimToken}
  AND query_lock_until >= #{now}
